    k352: "Le MCP officiel Intercom est OAuth, mais l’enregistrement dynamique refuse notre callback (Intercom doit autoriser https://api.oceanleo.com/v1/mcp/oauth/callback). Après autorisation, collez l’URL MCP ou l’Access Token.",
