    k136: "Servidor MCP personalizado",
    k137: "Crie, edite e colabore no Tencent Docs. Faça a gestão de folhas, documentos e diapositivos em linguagem natural.",
    k138: "Crie, consulte e faça a gestão do Tencent Meeting na linha de comandos. Inicie reuniões, veja a agenda e gira os participantes.",
    k139: "MCP do WeCom para mensagens, documentos, calendário, reuniões e tarefas (empresas até 10 pessoas; mais consoante o plano).",
    k140: "Veja, descarregue e elimine ficheiros Weiyun; carregue e gere ligações de partilha.",
    k141: "Crie, gira e analise o Tencent Survey. Redija inquéritos, veja respostas e defina a lógica.",
    k142: "Trate tickets em linguagem natural (consultar, criar, atualizar, alterar estado) e veja agentes online e atendimento em direto.",
    k143: "Cite materiais e ficheiros da base de conhecimento e veja os detalhes.",
    k144: "Pesquise, crie e gira documentos na base Lexiang. Importe Markdown, organize por etiquetas e acompanhe atualizações.",
    k145: "Conector móvel Fubangshou: identidade WorkBuddy, pacotes de cena, registos de primeiro valor e reutilização, estado do pacote.",
    k146: "Gira o CNB em linguagem natural: repositórios, issues, PRs, pipelines e registos de artefactos.",
    k147: "Implemente um projeto full-stack no EdgeOne Pages e gere uma ligação de pré-visualização.",
    k148: "Desenvolvimento, implementação, depuração e diagnóstico full-stack. Apps web, miniprogramas WeChat, uni-app e mais.",
    k149: "Conector MCP low-code Qingflow: apps, dados, fluxos e configuração de portais.",
    k150: "Envie, receba, pesquise e organize o QQ Mail. Leia, resuma tópicos e gira pastas.",
    k151: "Ligue o correio via IMAP/SMTP: enviar, receber, pesquisar e descarregar anexos. Suporta 163, 126 e yeah.net.",
    k152: "Gira o Feishu/Lark na linha de comandos: chat, correio, calendário, docs, folhas e bitable.",
    k153: "Gira o DingTalk na linha de comandos: tabelas IA, assiduidade, calendário, grupos e bots, contactos e docs.",
    k154: "Gira requisitos, defeitos, tarefas e iterações. Veja o progresso, divida o trabalho, altere o estado e registe horas.",
    k155: "Crie, pesquise e gira o Kingsoft Docs (WPS na nuvem). Word, Excel, PDF, PPT e folhas inteligentes.",
    k156: "Ligue o Baidu Netdisk: navegar, pesquisar, descarregar e partilhar.",
    k157: "Consulte cotações globais, filtros, estudos, avisos e macros pelo Tongdaxin MCP.",
    k158: "Consulte dados empresariais pelo Tianyancha MCP: registo, sócios, risco judicial e PI.",
    k159: "Consulte e verifique o registo empresarial: sócios, controladores, beneficiários, executivos, investimentos e finanças.",
    k160: "Ligue o Hundsun Gildata MCP: dados financeiros, estudos, avisos, notícias, filtros e macros setoriais.",
    k161: "Assistente de despesas com IA: pedidos, reconhecimento de faturas, consulta e aprovação.",
    k162: "Pesquise normas e casos em modo semântico e por palavras (exata/aproximada). Resultados com o original pkulaw.com.",
    k163: "A Huayu dá ao agente ferramentas MCP de normas, peças de processo e dados empresariais.",
    k164: "Consulte clientes, avance oportunidades, trabalhe leads, reivindique o mar aberto e escreva follow-ups: o ciclo de vendas.",
    k165: "Consulte ou gira no WeCom clientes, etiquetas, grupos, materiais, campanhas, envios em massa e follow-ups.",
    k166: "Ligue o Xiaoetong em linguagem natural: gestão de cursos e carregamento de materiais — consultar, criar, estruturar.",
    k167: "Obtenha planos e guias pela API Ctrip Wendao: hotéis, voos, pontos, itinerários, comida e alojamento.",
    k168: "Clone e envie no GitHub, veja e gira repositórios e pull requests, colabore em linguagem natural.",
    k169: "Crie, pesquise e gira workspaces Notion. Leia páginas, consulte bases, atualize conteúdo e organize.",
    k170: "Chame modelos e ferramentas da OpenAI (chat, imagem, recuperação). Dirija a plataforma em linguagem natural.",
    k171: "Ligue a plataforma Anthropic Claude. Chame modelos e ferramentas Claude em linguagem natural.",
    k172: "Ligue o Google Gemini para gerar, compreender e tarefas multimodais em linguagem natural.",
    k173: "Ligue o Grok da xAI para conversa e raciocínio em linguagem natural.",
    k174: "Chame centenas de grandes modelos pelo OpenRouter. Escolha e invoque em linguagem natural.",
    k175: "Use a pesquisa e o Q&A da Perplexity para dar ao agente resultados em tempo real com citações.",
