    k287: "Bấm 「Ủy quyền một chạm」 để đăng nhập Close và cấp quyền; hoặc điền API Key ở mục Nâng cao.",
    k288: "Bấm 「Ủy quyền một chạm」 để đăng nhập Apollo.io và cấp quyền; hoặc điền API Key ở mục Nâng cao.",
    k289: "Bấm 「Ủy quyền một chạm」 để đăng nhập monday.com; hoặc điền URL MCP / Token ở mục Nâng cao.",
