    k292: "Dán địa chỉ MCP được lưu của Anthropic (hoặc URL MCP riêng từ nền tảng lưu); nếu cần thì điền API Key.",
    k293: "Dán địa chỉ MCP được lưu của Google Gemini (hoặc URL MCP riêng từ nền tảng lưu); nếu cần thì điền API Key.",
    k294: "Dán địa chỉ MCP được lưu của Grok (xAI) (hoặc URL MCP riêng từ nền tảng lưu); nếu cần thì điền API Key.",
    k295: "Dán địa chỉ MCP được lưu của Perplexity (hoặc URL MCP riêng từ nền tảng lưu); nếu cần thì điền API Key.",
    k296: "Dán địa chỉ MCP được lưu của Cohere (hoặc URL MCP riêng từ nền tảng lưu); nếu cần thì điền API Key.",
    k297: "Dán địa chỉ MCP được lưu của Kling (hoặc URL MCP riêng từ nền tảng lưu); nếu cần thì điền API Key.",
    k298: "Dán địa chỉ MCP được lưu của Flux (BFL) (hoặc URL MCP riêng từ nền tảng lưu); nếu cần thì điền API Key.",
    k299: "Dán địa chỉ MCP được lưu của Tripo AI (hoặc URL MCP riêng từ nền tảng lưu); nếu cần thì điền API Key.",
    k300: "Dán địa chỉ MCP được lưu của Mailchimp (hoặc URL MCP riêng từ nền tảng lưu); nếu cần thì điền API Key.",
    k301: "Dán địa chỉ MCP được lưu của RevenueCat (hoặc URL MCP riêng từ nền tảng lưu); nếu cần thì điền API Key.",
    k302: "Dán địa chỉ MCP được lưu của Similarweb (hoặc URL MCP riêng từ nền tảng lưu); nếu cần thì điền API Key.",
    k303: "MCP chính thức của tl;dv là OAuth, nhưng đăng ký động hiện từ chối callback của chúng tôi. Sau khi ủy quyền, dán URL MCP riêng bên dưới.",
    k304: "MCP chính thức của Semrush là OAuth, nhưng đăng ký động hiện từ chối callback của chúng tôi. Sau khi ủy quyền, dán URL MCP riêng bên dưới.",
    k305: "MCP chính thức của Indeed là OAuth, nhưng đăng ký động hiện từ chối callback của chúng tôi. Sau khi ủy quyền, dán URL MCP riêng bên dưới.",
    k306: "MCP chính thức của PagerDuty có OAuth nhưng không có đăng ký client động. Sau khi ủy quyền tại PagerDuty, dán URL MCP hoặc token bên dưới.",
    k307: "MCP chính thức của DocuSign có OAuth nhưng không có đăng ký client động. Sau khi ủy quyền tại DocuSign, dán URL MCP hoặc token bên dưới.",
    k308: "Bấm 「Ủy quyền một chạm」 để đăng nhập Linear — không cần sao Token.",
    k309: "Bấm 「Ủy quyền một chạm」 để đăng nhập Neon — không cần sao Token.",
