    k311: "Bấm 「Ủy quyền một chạm」 để đăng nhập Dropbox — không cần sao Token.",
    k312: "Bấm 「Ủy quyền một chạm」 để đăng nhập Mixpanel và cấp quyền.",
    k313: "Bấm 「Ủy quyền một chạm」 để đăng nhập Explorium và cấp quyền.",
    k314: "Bấm 「Ủy quyền một chạm」 để đăng nhập Attio và cấp quyền.",
    k315: "Bấm 「Ủy quyền một chạm」 để đăng nhập Ramp và cấp quyền.",
