    k137: "Tencent Docs’ta oluşturun, düzenleyin ve iş birliği yapın. Çevrimiçi tablo, belge ve slaytları doğal dille yönetin.",
    k138: "Komut satırından Tencent Meeting oluşturun, sorgulayın ve yönetin. Toplantı başlatın, takvimi görün, katılımcıları yönetin.",
    k139: "WeCom MCP: mesaj, belge, takvim, toplantı ve yapılacaklar (10 kişiye kadar şirketler; daha fazlası plana göre).",
    k140: "Weiyun dosyalarını görüntüleyin, indirin, silin; yükleyin ve paylaşım bağlantısı oluşturun.",
    k141: "Tencent Survey oluşturun, yönetin ve analiz edin. Anket yazın, yanıtları görün, soru mantığını ayarlayın.",
    k142: "Doğal dille ticket işleyin (sorgula/oluştur/güncelle/durum) ve çevrimiçi ajan ile canlı karşılama durumunu görün.",
    k143: "Bilgi bankası materyalini alıntılayın ve ayrıntılara bakın.",
    k144: "Lexiang bilgi bankasında belge arayın, oluşturun ve yönetin. Markdown içe aktarın, etiketleyin, güncellemeleri izleyin.",
