    k146: "CNB platformunu doğal dille yönetin: depo, issue, PR, pipeline ve artefakt kayıtları.",
    k147: "Tam yığın projeyi EdgeOne Pages’e hızla dağıtın ve önizleme bağlantısı alın.",
