    k303: "tl;dv resmi MCP’si OAuth, ancak dinamik kayıt şu an geri çağırmamızı reddediyor. Yetkilendirdikten sonra kişisel MCP URL’sini aşağıya yapıştırın.",
    k304: "Semrush resmi MCP’si OAuth, ancak dinamik kayıt şu an geri çağırmamızı reddediyor. Yetkilendirdikten sonra kişisel MCP URL’sini aşağıya yapıştırın.",
    k305: "Indeed resmi MCP’si OAuth, ancak dinamik kayıt şu an geri çağırmamızı reddediyor. Yetkilendirdikten sonra kişisel MCP URL’sini aşağıya yapıştırın.",
    k306: "PagerDuty resmi MCP’sinde OAuth var ama dinamik istemci kaydı yok. PagerDuty yetkilendirmesinden sonra kişisel MCP URL veya jetonu yapıştırın.",
    k307: "DocuSign resmi MCP’sinde OAuth var ama dinamik istemci kaydı yok. DocuSign yetkilendirmesinden sonra kişisel MCP URL veya jetonu yapıştırın.",
    k308: "“Tek dokunuşla yetkilendir”e basıp Linear oturumu açın — jeton kopyalamanız gerekmez.",
    k309: "“Tek dokunuşla yetkilendir”e basıp Neon oturumu açın — jeton kopyalamanız gerekmez.",
    k310: "“Tek dokunuşla yetkilendir”e basıp PayPal oturumu açın — jeton kopyalamanız gerekmez.",
    k311: "“Tek dokunuşla yetkilendir”e basıp Dropbox oturumu açın — jeton kopyalamanız gerekmez.",
    k312: "“Tek dokunuşla yetkilendir”e basıp Mixpanel oturumu açın ve erişim verin.",
