    k326: "點「一鍵授權」跳轉 GitHub 登入並勾選權限即可（注意：GitHub 官方遠端 MCP 的 OAuth 需要帳號具備 Copilot 許可；若無 Copilot，請用「進階」貼上 Personal Access Token）。",
    k327: "點「一鍵授權」跳轉 Notion 登入並選擇要授權的頁面即可，無需手動建立整合或複製 Token。",
    k328: "貼上你的 OpenAI MCP 託管地址（或經 Composio/Zapier 產生的個人 MCP URL）；如需鑑權再填 API Key（作為 Authorization 頭）。",
    k329: "點「一鍵授權」跳轉 Hugging Face 登入並授權即可（建議）；或到 huggingface.co/settings/mcp 拿 Access Token 手動貼上（進階）。",
    k330: "ElevenLabs 官方 MCP 有 OAuth，但不提供動態用戶端註冊。到控制台拿 API Key，或授權後把個人 MCP URL 貼到下方。",
    k331: "Slack 只允許已上架 Slack Marketplace 的應用使用 MCP，我們的應用還在上架流程中，所以這裡暫時沒有一鍵授權。請按 Slack 官方 MCP 文件在自己的工作區建立內部應用後，把專屬服務地址和權杖貼到下方。",
    k332: "Asana V2 MCP 已取消動態用戶端註冊，必須先在 Asana 開發者控制台建立 MCP 應用。授權後把帶權杖的個人 MCP URL 貼到下方（端點：https://mcp.asana.com/v2/mcp）。",
    k333: "點「一鍵授權」跳轉 Atlassian 登入並授權即可（Jira / Confluence）。無瀏覽器時可用 API Token 走進階貼上。",
    k334: "點「一鍵授權」跳轉 Airtable 選擇工作區/庫並授權即可，無需複製 Personal Access Token。",
