    k338: "微軟沒有面向個人收件匣的固定公共 MCP。Microsoft 企業 MCP（mcp.svc.cloud.microsoft/enterprise）是租戶目錄查詢，不是 Outlook。把你租戶/自建的 Outlook MCP 地址貼到下方。",
    k339: "微軟沒有面向個人日曆的固定公共 MCP。把你租戶/自建的 Outlook 日曆 MCP 地址貼到下方。",
    k340: "點「一鍵授權」跳轉 Sentry 官方授權頁登入並勾選權限即可，無需複製 Token。",
    k341: "Vercel 官方 MCP 是 OAuth，但其動態註冊目前拒收我們的回呼地址（需 Vercel 把 https://api.oceanleo.com/v1/mcp/oauth/callback 加入允許名單）。授權後把帶權杖的個人 MCP URL 貼到下方。",
    k342: "點「一鍵授權」跳轉 Cloudflare 登入並授權即可（預設連 Workers Bindings）。",
