    k351: "HubSpot 官方遠端 MCP 要求先在 HubSpot 裡建立 MCP Auth App（不支援動態註冊）。授權後把個人 MCP URL 或 Private App Token 貼到下方。",
    k352: "Intercom 官方 MCP 是 OAuth，但其動態註冊目前拒收我們的回呼地址（需 Intercom 把 https://api.oceanleo.com/v1/mcp/oauth/callback 加入允許名單）。授權後把帶權杖的個人 MCP URL 或 Access Token 貼到下方。",
    k353: "點「一鍵授權」跳轉 Stripe 登入並授權即可（建議）；或到控制台建立受限金鑰後走進階貼上。",
