    k357: "ZoomInfo 官方 MCP 是 OAuth，但動態註冊只接受其批准廠商名單裡的名字。授權後把個人 MCP URL 或 API Key 貼到下方。",
    k358: "把你自建 Metabase 的 MCP 地址貼到下方；如需鑑權填 API Key。",
    k359: "點「一鍵授權」跳轉 PostHog 登入並授權即可；或把 Personal API Key 填到進階項。",
    k360: "Canva 的動態註冊接受我們的回呼，但授權頁仍拒絕它，所以這裡沒有一鍵授權。請到 canva.dev 的 MCP 文件按指引拿到你的專屬服務地址，貼到下方。",
    k361: "Figma 官方遠端 MCP 只接受其目錄裡的客戶端；對我們的回呼動態登記回傳 403。在 Figma 支援的客戶端完成授權後，把個人 MCP 工作階段地址貼到下方。",
