    k363: "點「一鍵授權」跳轉 GitLab 登入並授權即可（預設連 gitlab.com；自建實例請走自訂 MCP）。",
    k364: "點「一鍵授權」跳轉 Jam 登入並授權即可。之後把 Jam 連結發給 Agent 即可帶上完整排障上下文。",
    k365: "點「一鍵授權」跳轉 Datadog 登入並授權即可（預設美區；歐區站點請走自訂 MCP 填 mcp.datadoghq.eu）。",
    k366: "點「一鍵授權」跳轉 Amplitude 登入並授權即可（預設美區；歐區請走自訂 MCP 填 mcp.eu.amplitude.com）。",
