    k368: "Box 官方遠端 MCP 要求先在 Box 管理後台設定 OAuth 應用（無動態登記）。完成後把個人 MCP URL 或 Token 貼到下方。",
    k369: "Square 官方 MCP 是 OAuth，但其動態註冊拒收我們的回呼（網域不在允許名單）。授權後把個人 MCP URL 貼到下方。",
    k370: "Shopify 店面 MCP 按店鋪分開，沒有一張公共地址。把 https://你的店.myshopify.com/api/mcp 貼到下方（店面介面通常不用再貼 Token）。",
    k371: "Salesforce 官方託管 MCP 帶租戶與應用 ID，沒有固定公共地址。在 Salesforce 安裝包裡複製你的 MCP URL，貼到下方。",
    k372: "Dify 為每個應用單獨產生 MCP 地址（地址裡帶憑證）。到應用設定裡打開 MCP Server，把專屬 URL 貼到下方。",
