    k338: "Microsoft に個人受信トレイ向けの固定公開 MCP はない。企業 MCP（mcp.svc.cloud.microsoft/enterprise）はテナントディレクトリ照会であり Outlook ではない。テナント/自前の Outlook MCP URL を貼る。",
