    k350: "先に MCP サービスアドレスを入れる。標準リモート認可に対応していれば「ワンタップ認可」。そうでなければトークンを詳細に入れる。",
    k351: "HubSpot 公式リモート MCP は先に MCP Auth App を作る必要がある（動的登録なし）。認可後、個人 MCP URL か Private App Token を貼る。",
