    k371: "Salesforce 公式ホスト MCP はテナントとアプリ ID 付きで、固定公開アドレスはない。インストールパッケージから MCP URL をコピーして貼る。",
    k372: "Dify はアプリごとに MCP アドレスを出す（アドレスに資格情報が入る）。アプリ設定で MCP Server を開き、専用 URL を貼る。",
