    k323: "「원탭 승인」으로 텐센트 문서에 로그인하세요(권장). 또는 docs.qq.com/open/auth/mcp.html에서 개인 토큰을 받아 고급에 붙여 넣으세요.",
    k324: "텐센트 클라우드 MCP 광장의 「텐센트 회의」에서 파라미터를 채운 뒤 「Connect Server」를 누르고 생성된 SSE URL을 붙여 넣으세요.",
    k325: "톈옌 AI 데이터 플랫폼(ai.tianyancha.com)에서 API 키를 받아 아래 Authorization 헤더로 붙여 넣으세요.",
    k326: "「원탭 승인」으로 GitHub에 로그인하고 권한을 고르세요(공식 원격 MCP OAuth는 Copilot 라이선스 계정이 필요합니다. 없으면 고급에 Personal Access Token을 붙여 넣으세요).",
    k327: "「원탭 승인」으로 Notion에 로그인하고 권한을 줄 페이지를 고르세요. 통합을 만들거나 토큰을 복사할 필요 없습니다.",
    k328: "OpenAI 호스팅 MCP 주소(또는 Composio/Zapier 개인 URL)를 붙여 넣으세요. 인증이 필요하면 API 키를 Authorization 헤더로 넣으세요.",
    k329: "「원탭 승인」으로 Hugging Face에 로그인하세요(권장). 또는 huggingface.co/settings/mcp에서 Access Token을 받아 고급에 붙여 넣으세요.",
    k330: "ElevenLabs 공식 MCP는 OAuth가 있지만 동적 클라이언트 등록은 없습니다. 콘솔에서 API 키를 받거나, 승인 후 개인 MCP URL을 붙여 넣으세요.",
    k331: "Slack은 Marketplace에 올라간 앱만 MCP를 쓸 수 있습니다. 우리 앱은 아직 등록 중이라 원탭 승인이 없습니다. 공식 MCP 문서대로 워크스페이스에 내부 앱을 만든 뒤 전용 URL과 토큰을 붙여 넣으세요.",
    k332: "Asana V2 MCP는 동적 클라이언트 등록을 없앴습니다. 먼저 개발자 콘솔에서 MCP 앱을 만드세요. 승인 후 토큰이 담긴 개인 MCP URL을 붙여 넣으세요(https://mcp.asana.com/v2/mcp).",
    k333: "「원탭 승인」으로 Atlassian(Jira / Confluence)에 로그인하세요. 브라우저가 없으면 고급에 API Token을 붙여 넣으세요.",
    k334: "「원탭 승인」으로 Airtable 워크스페이스/베이스를 고르세요. Personal Access Token을 복사할 필요 없습니다.",
