    k336: "「원탭 승인」으로 Google에 로그인하세요(권장, 공식 Calendar MCP에 연결).",
    k337: "「원탭 승인」으로 Google에 로그인하세요(권장, 공식 Drive MCP에 연결).",
    k338: "Microsoft에는 개인 받은편지함용 고정 공개 MCP가 없습니다. 엔터프라이즈 MCP(mcp.svc.cloud.microsoft/enterprise)는 테넌트 디렉터리 조회이지 Outlook이 아닙니다. 테넌트/자체 Outlook MCP URL을 붙여 넣으세요.",
    k339: "Microsoft에는 개인 캘린더용 고정 공개 MCP가 없습니다. 테넌트/자체 Outlook 캘린더 MCP URL을 붙여 넣으세요.",
    k340: "「원탭 승인」으로 Sentry 공식 승인 페이지에 로그인하고 권한을 고르세요. 토큰을 복사할 필요 없습니다.",
    k341: "Vercel 공식 MCP는 OAuth이지만 동적 등록이 우리 콜백을 거절합니다(Vercel이 https://api.oceanleo.com/v1/mcp/oauth/callback을 허용해야 함). 승인 후 토큰이 담긴 개인 MCP URL을 붙여 넣으세요.",
    k342: "「원탭 승인」으로 Cloudflare에 로그인하세요(기본은 Workers Bindings).",
    k343: "「원탭 승인」으로 Supabase에 로그인하세요. 또는 고급에 Personal Access Token / project_ref가 있는 주소를 넣으세요.",
    k344: "Playwright MCP는 보통 로컬/자체 실행입니다. 자체 또는 호스팅 Playwright MCP URL을 아래에 붙여 넣으세요.",
    k345: "「원탭 승인」으로 Zapier에 로그인하세요. 또는 mcp.zapier.com에서 전용 URL을 만들어 고급에 붙여 넣으세요.",
    k346: "내 n8n 인스턴스에서 MCP 트리거를 켠 뒤 그 개인 MCP URL을 붙여 넣으세요. 인증이 필요하면 토큰을 넣으세요.",
    k347: "「원탭 승인」으로 Apify에 로그인하세요. 또는 콘솔에서 API Token을 받아 고급에 넣으세요.",
    k348: "「원탭 승인」으로 Firecrawl에 로그인하고 팀을 고르세요. 또는 고급에 API 키를 넣으세요.",
    k349: "자체/호스팅 「브라우저 MCP」 주소를 붙여 넣으면 에이전트가 당신 브라우저 맥락에서 페이지를 조작합니다.",
    k350: "먼저 MCP 서비스 주소를 넣으세요. 표준 원격 승인을 지원하면 「원탭 승인」을 누르고, 아니면 고급에 토큰을 넣으세요.",
    k351: "HubSpot 공식 원격 MCP는 먼저 HubSpot에서 MCP Auth App을 만들어야 합니다(동적 등록 없음). 승인 후 개인 MCP URL 또는 Private App Token을 붙여 넣으세요.",
    k352: "Intercom 공식 MCP는 OAuth이지만 동적 등록이 우리 콜백을 거절합니다(Intercom이 https://api.oceanleo.com/v1/mcp/oauth/callback을 허용해야 함). 승인 후 개인 MCP URL 또는 Access Token을 붙여 넣으세요.",
    k353: "「원탭 승인」으로 Stripe에 로그인하세요(권장). 또는 콘솔에서 제한 키를 만들어 고급에 붙여 넣으세요.",
    k354: "Xero 공식 MCP는 개발자 콘솔에서 앱을 미리 등록해야 합니다(동적 등록 없음). 승인 후 개인 MCP URL 또는 토큰을 붙여 넣으세요.",
    k355: "Polygon 호스팅 MCP 주소(승인 후 개인 URL)를 붙여 넣고, Polygon에서 API 키를 받아 아래에 넣으세요.",
    k356: "「원탭 승인」으로 Ahrefs에 로그인하세요(MCP 권한이 있는 계정 필요). 또는 고급에 API 키를 넣으세요.",
    k357: "ZoomInfo 공식 MCP는 OAuth이지만 동적 등록은 승인 벤더 목록의 이름만 받습니다. 승인 후 개인 MCP URL 또는 API 키를 붙여 넣으세요.",
    k358: "자체 Metabase MCP 주소를 붙여 넣으세요. 인증이 필요하면 API 키를 넣으세요.",
    k359: "「원탭 승인」으로 PostHog에 로그인하세요. 또는 고급에 Personal API Key를 넣으세요.",
    k360: "Canva 동적 등록은 우리 콜백을 받지만 승인 페이지가 거절하므로 원탭 승인이 없습니다. canva.dev MCP 문서대로 전용 URL을 받아 붙여 넣으세요.",
    k361: "Figma 공식 원격 MCP는 디렉터리의 클라이언트만 받습니다. 우리 콜백의 동적 등록은 403입니다. 지원 클라이언트에서 승인한 뒤 개인 MCP 세션 URL을 붙여 넣으세요.",
