    k136: "خادم MCP مخصص",
    k137: "أنشئ مستندات Tencent وحرّرها وتعاون عليها. أدِر الجداول والمستندات والشرائح بلغة طبيعية.",
    k138: "أنشئ اجتماعات Tencent واستعلم عنها وأدِرها من سطر الأوامر. ابدأ الاجتماعات وراجع الجدول وأدِر الحضور.",
    k139: "قدرات MCP لـ WeCom: رسائل ومستندات وتقويم واجتماعات ومهام (للشركات حتى 10 أشخاص؛ المزيد حسب الخطة).",
    k140: "اعرض ملفات Weiyun ونزّلها واحذفها؛ ارفعها وأنشئ روابط مشاركة.",
    k141: "أنشئ استبيانات Tencent وأدِرها وحلّلها. صغ الأسئلة وراجع الردود واضبط المنطق بلغة طبيعية.",
    k142: "عالج التذاكر بلغة طبيعية (استعلام/إنشاء/تحديث/تغيير الحالة) وتحقق من حضور الوكلاء والاستقبال المباشر.",
    k143: "استشهد بمواد وملفات قاعدة المعرفة وتصفّح تفاصيلها.",
    k144: "ابحث في مستندات Lexiang وأنشئها وأدِرها. استورد Markdown ونظّم بالوسوم وتتبع التحديثات.",
    k145: "موصّل هاتف Fubangshou: هوية WorkBuddy وحزم المشاهد وسجلات القيمة الأولى وإعادة الاستخدام وحالة الحزمة.",
    k146: "أدِر منصة CNB بلغة طبيعية: المستودعات والمسائل وطلبات الدمج والأنابيب وسجلات القطع.",
    k147: "انشر مشروعًا كامل المكدس على EdgeOne Pages بسرعة وأنشئ رابط معاينة.",
    k148: "تطوير ونشر وتصحيح وتشخيص كامل المكدس. تطبيقات ويب وميني برامج WeChat وuni-app وغيرها.",
    k149: "موصّل MCP منخفض الكود لـ Qingflow: بناء التطبيقات والبيانات والتدفقات وإعداد البوابات.",
    k150: "أرسل بريد QQ واستقبله وابحث فيه ونظّمه. اقرأ الرسائل ولخّص السلاسل وأدِر المجلدات.",
    k151: "اتصل بالبريد عبر IMAP/SMTP: إرسال واستقبال وبحث وتنزيل المرفقات. يدعم 163 و126 وyeah.net.",
    k152: "أدِر Feishu/Lark من سطر الأوامر: الدردشة والبريد والتقويم والمستندات والجداول وbitable.",
    k153: "أدِر DingTalk من سطر الأوامر: جداول الذكاء وجدولة الحضور والتقويم والمجموعات والبوتات وجهات الاتصال.",
    k154: "أدِر المتطلبات والعيوب والمهام والتكرارات. راجع التقدم وقسّم العمل وغيّر الحالة وسجّل الساعات.",
    k155: "أنشئ مستندات Kingsoft وابحث فيها وأدِرها (سحابة WPS). Word وExcel وPDF وPPT وجداول ذكية.",
    k156: "اربط بايدو نت ديسك: تصفّح وابحث ونزّل وشارك.",
    k157: "استعلم عبر Tongdaxin MCP عن الأسعار العالمية والفرز والأبحاث والإعلانات والبيانات الكلية.",
    k158: "استعلم عبر Tianyancha MCP عن بيانات الشركات: السجل والمساهمين والمخاطر القضائية والملكية الفكرية.",
    k159: "تحقق من سجل الشركات: المساهمون والمتحكمون والمستفيدون والمديرون والاستثمارات والمالية.",
    k160: "اربط Hundsun Gildata MCP للبيانات المالية والأبحاث والإعلانات والأخبار والفرز والبيانات الكلية.",
    k161: "مساعد مصروفات سحابي بالذكاء: قدّم الطلبات وتعرّف الفواتير واستعلم عن التقارير ووافق على التكاليف.",
    k162: "ابحث في القوانين والقضايا دلاليًا وبالكلمات (دقيق/ضبابي). النتائج تتضمن أصل pkulaw.com.",
    k163: "تمنح بيانات Huayu الوكيل أدوات MCP للقوانين ووثائق القضايا ومعلومات الشركات.",
    k164: "ابحث عن العملاء وادفع الفرص ونظّم العملاء المحتملين وخُذ البحر المفتوح واكتب المتابعة — حلقة المبيعات.",
    k165: "استعلم عن عملاء WeCom أو أدِرهم: الوسوم والمجموعات والمواد والحملات والإرسال الجماعي والمتابعة.",
    k166: "اربط Xiaoetong بلغة طبيعية لإدارة الدورات ورفع المواد: استعلام وإنشاء وهيكلة.",
    k167: "احصل على خطط وأدلة السفر من واجهة Ctrip Wendao: فنادق ورحلات ومعالم ومسارات وطعام وإقامة.",
    k168: "انسخ وادفع على GitHub وأدِر المستودعات وطلبات الدمج وتعاون على الشيفرة بلغة طبيعية.",
    k169: "أنشئ مساحات Notion وابحث فيها وأدِرها. اقرأ الصفحات واستعلم عن القواعد وحدّث المحتوى.",
    k170: "استدعِ نماذج وأدوات OpenAI (محادثة وصور واسترجاع) وشغّل موارد المنصة بلغة طبيعية.",
    k171: "اربط قدرات منصة Anthropic Claude. استدعِ نماذج وأدوات Claude بلغة طبيعية.",
