    k178: "تحويل النص إلى كلام واستنساخ الصوت ومعالجة الصوت. أنشئ تعليقًا صوتيًا عالي الجودة بلغة طبيعية.",
    k179: "أنشئ فيديوهات البشر الرقميين وبث الذكاء. أنشئ فيديوهات ناطقة وأدِر الصور الرمزية والمواد.",
