    k187: "أدِر لوحات ومشاريع وأتمتة monday.com. استعلم عن عناصر العمل وحدّثها بلغة طبيعية.",
    k188: "أدِر مهام ومستندات وأهداف ClickUp. أنشئ عناصر العمل وابحث عنها وحرّكها بلغة طبيعية.",
