    k330: "MCP الرسمي لـ ElevenLabs يدعم OAuth دون تسجيل عميل ديناميكي. خذ مفتاح API من لوحة التحكم أو الصق عنوان MCP الشخصي بعد السماح.",
    k331: "Slack يسمح بـ MCP لتطبيقات Marketplace فقط. تطبيقنا ما زال في مسار الإدراج، فلا تفويض بنقرة هنا. اتبع وثائق Slack، أنشئ تطبيقًا داخليًا، ثم الصق عنوان الخدمة والرمز.",
    k332: "أسانا V2 MCP ألغى التسجيل الديناميكي — أنشئ تطبيق MCP في وحدة المطوّر أولًا. بعد السماح الصق عنوان MCP الشخصي مع الرمز (https://mcp.asana.com/v2/mcp).",
    k333: "انقر «تفويض بنقرة» لتسجيل الدخول إلى Atlassian (Jira / Confluence). بلا متصفح الصق رمز API في المتقدم.",
