    k338: "لا يوجد لدى Microsoft MCP عام ثابت لصندوق وارد شخصي. MCP المؤسسة (mcp.svc.cloud.microsoft/enterprise) يستعلم دليل المستأجر وليس Outlook. الصق عنوان Outlook MCP لمستأجرك أو المستضاف ذاتيًا.",
    k339: "لا يوجد لدى Microsoft MCP عام ثابت لتقويم شخصي. الصق عنوان Outlook Calendar MCP لمستأجرك أو المستضاف ذاتيًا.",
    k340: "انقر «تفويض بنقرة» لتسجيل الدخول إلى صفحة تفويض Sentry الرسمية وتحديد الصلاحيات — دون نسخ رمز.",
    k341: "MCP الرسمي لـ Vercel يعمل بـ OAuth، لكن التسجيل الديناميكي يرفض رد النداء (يجب أن تسمح Vercel بـ https://api.oceanleo.com/v1/mcp/oauth/callback). بعد السماح الصق عنوان MCP الشخصي مع الرمز.",
    k342: "انقر «تفويض بنقرة» لتسجيل الدخول إلى Cloudflare (الافتراضي Workers Bindings).",
