    k344: "Playwright MCP يعمل عادة محليًا أو مستضافًا ذاتيًا. الصق عنوان Playwright MCP المستضاف ذاتيًا أو المستضاف أدناه.",
    k345: "انقر «تفويض بنقرة» لتسجيل الدخول إلى Zapier؛ أو أنشئ عنوانًا في mcp.zapier.com والصقه في المتقدم.",
