    k348: "انقر «تفويض بنقرة» لتسجيل الدخول إلى Firecrawl واختيار فريق؛ أو ضع مفتاح API في المتقدم.",
    k349: "الصق عنوان «متصفح MCP» المستضاف ذاتيًا أو المستضاف ليعمل الوكيل في سياق متصفحك.",
    k350: "املأ عنوان خدمة MCP أولًا. إن دعم التفويض البعيد القياسي فانقر «تفويض بنقرة»؛ وإلا ضع الرمز في المتقدم.",
    k351: "MCP البعيد الرسمي لـ HubSpot يطلب إنشاء تطبيق MCP Auth أولًا (بلا تسجيل ديناميكي). بعد السماح الصق عنوان MCP أو رمز التطبيق الخاص.",
    k352: "MCP الرسمي لـ Intercom يعمل بـ OAuth، لكن التسجيل الديناميكي يرفض رد النداء (يجب أن تسمح Intercom بـ https://api.oceanleo.com/v1/mcp/oauth/callback). بعد السماح الصق عنوان MCP أو رمز الوصول.",
